float _VoronoiSmoothnessA = 0.5;
float _VoronoiSmoothnessB = 0.5;
float _VoronoiSmoothnessC = 0.5;
float _VoronoiSpeedA = 0.5;
float _VoronoiSpeedB = 0.5;
float _VoronoiSpeedC = 0.5;
float _VoronoiScaleA = 150.0;
float _VoronoiScaleB = 100.0;
float _VoronoiScaleC =  50.0;
float _VoronoiPower = 1.0;
vec4 _VoronoiColor = vec4(1,1,1,1);

vec3 Hash(vec2 p)
{
	float a = dot(p, vec2(127.1, 311.7));
	float b = dot(p, vec2(269.5, 183.3));
	float c = dot(p, vec2(419.2, 371.9));
	return fract(sin(vec3(a, b, c)) * 43758.5453);
}

float Voronoi(vec2 uv, float weight, float speed)
{
	vec2 cell = floor(uv);
	vec2 fraction = fract(uv);
	float minDistance = 8.0;
	for(int j=-1; j<=1; j++)
	{
		for(int i=-1; i<=1; i++)
		{
			vec2 offset = vec2(float(i), float(j));
			vec2 neighbor = cell + offset;
			vec3 hash = Hash(neighbor);
			float currentDistance = length(offset - fraction + hash.xy);
			float scale = hash.x * hash.y;
			float time = fract(iTime * speed);
			if (hash.z < time) scale = scale * time;
			currentDistance += scale;
			float blendFactor = smoothstep(-1.0, 1.0, (minDistance - currentDistance) / weight);
			minDistance = mix(minDistance, currentDistance, blendFactor);
			minDistance -= blendFactor * (1.0 - blendFactor) * weight / (1.0 + 3.0 * weight);
		}
	}
	return minDistance;
}

float Foam(vec2 p)
{
	float layer1 = Voronoi(_VoronoiScaleA * p, _VoronoiSmoothnessA, _VoronoiSpeedA);
	float layer2 = Voronoi(_VoronoiScaleB * p, _VoronoiSmoothnessB, _VoronoiSpeedB);
	float layer3 = Voronoi(_VoronoiScaleC * p, _VoronoiSmoothnessC, _VoronoiSpeedC);
	return pow(min(min(layer1, layer2), layer3), _VoronoiPower);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xx;
    float scale = 0.25;
    float foam = Foam(uv * scale);
    fragColor = vec4(foam * _VoronoiColor.rgb, 1.0);    
}
